use std::process::Command;
#[test]fn doctor_is_truthful_and_does_not_echo_invalid_endpoint(){let output=Command::new(env!("CARGO_BIN_EXE_local-node")).args(["doctor","--endpoint","https://synthetic-user:synthetic-secret@example.com/"]).output().unwrap();assert_eq!(output.status.code(),Some(2));let body=String::from_utf8(output.stdout).unwrap();assert!(!body.contains("synthetic-secret"));let value:serde_json::Value=serde_json::from_str(&body).unwrap();assert_eq!(value["network_started"],false);assert_eq!(value["listener"],"disabled");assert_eq!(value["endpoint"],"denied");}
#[test]fn unknown_arguments_never_echo_values(){let output=Command::new(env!("CARGO_BIN_EXE_local-node")).args(["doctor","--token","synthetic-private-value"]).output().unwrap();assert_eq!(output.status.code(),Some(2));assert!(!String::from_utf8_lossy(&output.stderr).contains("synthetic-private-value"));}
